#!/usr/bin/env bash
# AKFC — Demandes (tickets), incrément 5 : récapitulatif quotidien (qui sert de relance).
#  - un e-mail par ADRESSE de catégorie (admin@, support@ — jamais aux boîtes perso), chaque jour à
#    8 h (heure de Paris), SEULEMENT si le club a quelque chose à faire :
#      en retard · échéance sous 48 h · autres demandes en attente/en cours (« sans responsable »
#      signalé) ; les demandes répondues ne sont que comptées. Lien direct par demande.
#  - réglages (env, facultatifs) : TICKET_RECAP_HOUR=8, TICKET_RECAP_DISABLED=1 pour couper.
#  Aucune migration, aucune dépendance. Preuve avant commit : pnpm check (sinon TOUT est restauré).
# Usage : bash apply-tickets-increment5.sh   (AKFC_APPLY_ONLY=1 : applique sans vérifier ni committer)
set -euo pipefail
[ -f "package.json" ] || { echo "ERREUR: racine du repo." >&2; exit 1; }
F="packages/backend/src/modules/tickets/recap.service.ts"; INS=apps/web/src/instrumentation.ts
[ -f packages/backend/src/modules/tickets/imapIntake.service.ts ] || { echo "ERREUR: applique d'abord apply-tickets-increment4.sh." >&2; exit 1; }
[ -f "$F" ] && { echo "— déjà appliqué"; exit 0; }
BK=/tmp/akfc_tk5_backup; rm -rf "$BK"; mkdir -p "$BK"; cp "$INS" "$BK/ins"
restore(){ cp "$BK/ins" "$INS"; rm -f "$F"; echo "↩ fichiers restaurés à l'identique (aucun commit)."; }
W=/tmp/akfc_tk5; rm -rf "$W"; mkdir -p "$W"
echo '' | base64 -d > "$W/edit.py"

echo "== application =="
echo '' | base64 -d > "$F" && echo "  ok  $F"
python3 "$W/edit.py" . || { restore; exit 1; }

if [ "${AKFC_APPLY_ONLY:-0}" = "1" ]; then echo "APPLY_ONLY"; exit 0; fi

echo "== pnpm check =="
if ! pnpm check > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"; grep -nE "conventions Next|error TS|Error:" /tmp/akfc_tc.log | head -15; restore; exit 1
fi
echo "  ✅ check OK"

git add "$F" "$INS"
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
feat(tickets): récapitulatif quotidien des demandes par adresse de catégorie (relance)

